package com.emotetracker;

final class DanceSession
{
    private long dancingNanos;
    private long ravingNanos;
    private long longestNanos;
    private long segmentStartNanos;
    private long danceStartNanos;
    private int activations;
    private boolean active;
    private boolean raving;

    void observe(boolean dancing, boolean raving, long nowNanos)
    {
        if (!active)
        {
            if (dancing)
            {
                beginDance(nowNanos, raving);
            }
            return;
        }

        if (!dancing)
        {
            bankSegment(nowNanos);
            endDance(nowNanos);
            return;
        }

        if (raving != this.raving)
        {
            bankSegment(nowNanos);
            segmentStartNanos = nowNanos;
            this.raving = raving;
        }
    }

    private void beginDance(long nowNanos, boolean raving)
    {
        active = true;
        this.raving = raving;
        activations++;
        danceStartNanos = nowNanos;
        segmentStartNanos = nowNanos;
    }

    private void endDance(long nowNanos)
    {
        longestNanos = Math.max(longestNanos, nowNanos - danceStartNanos);
        active = false;
        raving = false;
    }

    private void bankSegment(long nowNanos)
    {
        long elapsedNanos = nowNanos - segmentStartNanos;

        if (raving)
        {
            ravingNanos += elapsedNanos;
        }
        else
        {
            dancingNanos += elapsedNanos;
        }
    }

    void reset(long nowNanos)
    {
        dancingNanos = 0;
        ravingNanos = 0;
        longestNanos = 0;
        activations = active ? 1 : 0;
        segmentStartNanos = nowNanos;
        danceStartNanos = nowNanos;
    }

    Snapshot snapshot(long nowNanos)
    {
        long elapsedNanos = active ? nowNanos - segmentStartNanos : 0;
        long currentDancingNanos = dancingNanos;
        long currentRavingNanos = ravingNanos;

        if (active && raving)
        {
            currentRavingNanos += elapsedNanos;
        }
        else if (active)
        {
            currentDancingNanos += elapsedNanos;
        }

        long currentLongestNanos = active ? Math.max(longestNanos, nowNanos - danceStartNanos) : longestNanos;
        return new Snapshot(currentDancingNanos, currentRavingNanos, currentLongestNanos, activations, active, raving);
    }

    static final class Snapshot
    {
        final long dancingNanos;
        final long ravingNanos;
        final long longestNanos;
        final int activations;
        final boolean active;
        final boolean raving;

        Snapshot(long dancingNanos, long ravingNanos, long longestNanos, int activations,
            boolean active, boolean raving)
        {
            this.dancingNanos = dancingNanos;
            this.ravingNanos = ravingNanos;
            this.longestNanos = longestNanos;
            this.activations = activations;
            this.active = active;
            this.raving = raving;
        }
    }
}

package com.emotetracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("emote-tracker")
public interface EmoteTrackerConfig extends Config
{
    @ConfigItem(keyName = "debugDetection", name = "Log detection changes",
        description = "Log local animation and graphic IDs for in-game verification")
    default boolean debugDetection()
    {
        return false;
    }
}

package com.emotetracker;

import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.PluginPanel;

final class EmoteTrackerPanel extends PluginPanel
{
    private final JLabel status = new JLabel("Not dancing");
    private final JLabel totalTime = new JLabel();
    private final JLabel dancingTime = new JLabel();
    private final JLabel ravingTime = new JLabel();
    private final JLabel sessionCount = new JLabel();
    private final JLabel longestDance = new JLabel();
    private String results = "";

    EmoteTrackerPanel(Runnable reset)
    {
        setLayout(new BorderLayout(0, 12));
        setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));

        JPanel stats = new JPanel(new GridLayout(0, 1, 0, 8));
        stats.add(new JLabel("Crab Rave Tracker"));
        stats.add(status);
        stats.add(totalTime);
        stats.add(dancingTime);
        stats.add(ravingTime);
        stats.add(sessionCount);
        stats.add(longestDance);
        add(stats, BorderLayout.NORTH);

        JPanel actions = new JPanel(new GridLayout(0, 1, 0, 8));
        JButton resetButton = new JButton("Reset Session");
        JButton copyButton = new JButton("Copy Results");

        resetButton.addActionListener(event -> reset.run());
        copyButton.addActionListener(event ->
        {
            if (!results.isEmpty())
            {
                Toolkit.getDefaultToolkit().getSystemClipboard()
                    .setContents(new StringSelection(results), null);
            }
        });

        actions.add(resetButton);
        actions.add(copyButton);
        add(actions, BorderLayout.SOUTH);
    }

    void render(DanceSession.Snapshot snapshot, String playerName)
    {
        String total = duration(snapshot.dancingNanos + snapshot.ravingNanos);
        String dancing = duration(snapshot.dancingNanos);
        String raving = duration(snapshot.ravingNanos);

        status.setText(statusText(snapshot));
        totalTime.setText(row("Total", total));
        dancingTime.setText(row("Dancing", dancing));
        ravingTime.setText(row("Raving", raving));
        sessionCount.setText(row("Dance sessions", Integer.toString(snapshot.activations)));
        longestDance.setText(row("Longest", duration(snapshot.longestNanos)));

        results = "Crab Rave Tracker " + playerName + "\n"
            + "**Total**: " + total + "\n"
            + "**Dancing**: " + dancing + "\n"
            + "**Raving**: " + raving + "\n"
            + "(V).{^m^}.(V)";
    }

    private static String statusText(DanceSession.Snapshot snapshot)
    {
        if (!snapshot.active)
        {
            return "Not dancing";
        }

        return snapshot.raving ? "Raving" : "Dancing";
    }

    private static String row(String label, String value)
    {
        return "<html><b>" + label + "</b>: " + value + "</html>";
    }

    static String duration(long nanos)
    {
        long hundredths = nanos / 10_000_000L;
        long minutes = hundredths / 6000;
        long seconds = (hundredths / 100) % 60;
        long centiseconds = hundredths % 100;

        return String.format("%02d:%02d.%02d", minutes, seconds, centiseconds);
    }
}

package com.emotetracker;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.AnimationID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(name = "Crab Rave Tracker", description = "Track Dancing and Raving time per session",
    tags = {"emote", "crab", "dance", "timer", "rave"})
public class EmoteTrackerPlugin extends Plugin
{
    private static final Logger LOG = LoggerFactory.getLogger(EmoteTrackerPlugin.class);

    private static final long PANEL_REFRESH_INTERVAL_NANOS = 100_000_000L;
    // FX_EMOTE_PARTY01_ACTIVE (confetti).
    private static final int CONFETTI_GRAPHIC = 2365;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ClientToolbar toolbar;

    @Inject
    private EmoteTrackerConfig config;

    private DanceSession session;
    private EmoteTrackerPanel panel;
    private NavigationButton navigation;
    private long lastRenderNanos;
    private volatile boolean running;
    private String lastLoggedState = "";

    @Provides
    EmoteTrackerConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(EmoteTrackerConfig.class);
    }

    @Override
    protected void startUp()
    {
        session = new DanceSession();
        panel = new EmoteTrackerPanel(this::resetSession);
        lastRenderNanos = 0;
        lastLoggedState = "";

        BufferedImage icon = ImageUtil.loadImageResource(EmoteTrackerPlugin.class, "icon.png");
        navigation = NavigationButton.builder()
            .tooltip("Crab Rave Tracker")
            .icon(icon)
            .priority(5)
            .panel(panel)
            .build();

        toolbar.addNavigation(navigation);
        running = true;
        EmoteTrackerPanel currentPanel = panel;
        clientThread.invokeLater(() ->
        {
            if (running && panel == currentPanel)
            {
                render();
            }
        });
    }

    @Override
    protected void shutDown()
    {
        running = false;
        toolbar.removeNavigation(navigation);
    }

    @Subscribe
    public void onAnimationChanged(AnimationChanged event)
    {
        if (running && event.getActor() == client.getLocalPlayer())
        {
            sample();
        }
    }

    @Subscribe
    public void onClientTick(ClientTick event)
    {
        if (!running)
        {
            return;
        }

        sample();
        long nowNanos = System.nanoTime();

        if (nowNanos - lastRenderNanos >= PANEL_REFRESH_INTERVAL_NANOS)
        {
            lastRenderNanos = nowNanos;
            render();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (running && event.getGameState() != GameState.LOGGED_IN)
        {
            session.observe(false, false, System.nanoTime());
            render();
        }
    }

    private void sample()
    {
        Player player = client.getLocalPlayer();
        boolean loggedIn = client.getGameState() == GameState.LOGGED_IN && player != null;
        int animation = loggedIn ? player.getAnimation() : -1;
        int graphic = loggedIn ? player.getGraphic() : -1;

        boolean dancing = isCrabDance(animation);
        boolean raving = isCrabRaving(animation, graphic);

        session.observe(dancing, raving, System.nanoTime());

        if (config.debugDetection() && loggedIn)
        {
            logDetectionChange(animation, graphic);
        }
    }

    static boolean isCrabDance(int animation)
    {
        return animation == AnimationID.HUMAN_EMOTE_CRABDANCE
            || animation == AnimationID.HUMAN_EMOTE_CRABDANCE_LOOP;
    }

    static boolean isCrabRaving(int animation, int graphic)
    {
        return isCrabDance(animation) && graphic == CONFETTI_GRAPHIC;
    }

    private void resetSession()
    {
        EmoteTrackerPanel currentPanel = panel;
        clientThread.invokeLater(() ->
        {
            if (!running || panel != currentPanel)
            {
                return;
            }

            sample();
            session.reset(System.nanoTime());
            render();
        });
    }

    private void logDetectionChange(int animation, int graphic)
    {
        String currentState = "animation=" + animation + ", graphic=" + graphic;

        if (currentState.equals(lastLoggedState))
        {
            return;
        }

        LOG.info("Crab Rave Tracker: {}", currentState);
        lastLoggedState = currentState;
    }

    private void render()
    {
        DanceSession.Snapshot snapshot = session.snapshot(System.nanoTime());
        Player player = client.getLocalPlayer();
        String playerName = player == null || player.getName() == null ? "Unknown player" : player.getName();

        EmoteTrackerPanel currentPanel = panel;
        SwingUtilities.invokeLater(() ->
        {
            if (running)
            {
                currentPanel.render(snapshot, playerName);
            }
        });
    }
}
